stView(padding:const EdgeInsets.all(14),children:[...d.$2.map((x){final p=x.split('|');return AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(p[0],style:const TextStyle(fontWeight:FontWeight.w800)),Text(p[1],style:const TextStyle(color:AppColors.muted))]));}),if(code==-9)AppCard(child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const Text('🌙 المظهر',style:TextStyle(fontWeight:FontWeight.w800)),Switch(value:AppScope.of(c).dark,onChanged:(v)=>AppScope.of(c).change(()=>AppScope.of(c).dark=v))]))]))])));}}
